<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/security.php';header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
function eventOut($d,$s=200){http_response_code($s);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
$m=$_SERVER['REQUEST_METHOD'];if($m==='GET'){$res=$db->query("SELECT id,title,description,category,event_date,venue,capacity,poster,status FROM events ORDER BY event_date");eventOut(['data'=>$res->fetch_all(MYSQLI_ASSOC)]);}
if(empty($_SESSION['user_id']))eventOut(['error'=>'Authentication required'],401);if(($_SESSION['user_role']??'')!=='admin')eventOut(['error'=>'Administrator access required'],403);if(!in_array($m,['POST','PUT','DELETE'],true))eventOut(['error'=>'Method not allowed'],405);sh_verify_csrf();$in=$_POST;if(str_contains($_SERVER['CONTENT_TYPE']??'','application/json'))$in=json_decode(file_get_contents('php://input'),true)??[];$id=(int)($in['id']??$_GET['id']??0);
try{if($m==='DELETE'){$s=$db->prepare('DELETE FROM events WHERE id=?');$s->bind_param('i',$id);$s->execute();$s->close();sh_audit($db,'delete','event',$id);eventOut(['message'=>'Event deleted']);}
$t=trim($in['title']??'');$d=trim($in['description']??'');$c=trim($in['category']??'General');$date=str_replace('T',' ',$in['event_date']??'');$v=trim($in['venue']??'');$cap=(int)($in['capacity']??100);$status=$in['status']??'published';if(!$t||!$d||!$date||!$v||$cap<1||!in_array($status,['published','draft','closed'],true))eventOut(['error'=>'Invalid event fields'],422);
if($m==='PUT'||$id){$s=$db->prepare('UPDATE events SET title=?,description=?,category=?,event_date=?,venue=?,capacity=?,status=? WHERE id=?');$s->bind_param('sssssisi',$t,$d,$c,$date,$v,$cap,$status,$id);$s->execute();$s->close();sh_audit($db,'update','event',$id);eventOut(['message'=>'Event updated','id'=>$id]);}
$uid=(int)$_SESSION['user_id'];$s=$db->prepare('INSERT INTO events(title,description,category,event_date,venue,capacity,status,created_by) VALUES(?,?,?,?,?,?,?,?)');$s->bind_param('sssssisi',$t,$d,$c,$date,$v,$cap,$status,$uid);$s->execute();$id=$s->insert_id;$s->close();sh_audit($db,'create','event',$id);eventOut(['message'=>'Event created','id'=>$id],201);
}catch(mysqli_sql_exception $e){eventOut(['error'=>'Database operation failed'],409);}
